#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;

namespace MVZ2.GameContent.Projectiles
{
    [EntityBehaviourDefinition(VanillaProjectileNames.vomit)]
    public class Vomit : ProjectileBehaviour
    {
        public Vomit(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.CollisionMaskHostile |= EntityCollisionHelper.MASK_PLANT;
        }
        public override void PostCollision(EntityCollision collision, int state)
        {
            base.PostCollision(collision, state);
            if (state == EntityCollisionHelper.STATE_EXIT)
                return;
            var self = collision.Entity;
            var other = collision.Other;
            if (!other.IsEntityOf(VanillaContraptionID.lightningOrb) || !self.IsHostile(other))
                return;
            if (!self.Exists())
                return;
            self.Remove();
            other.HealEffects(100, self);
            other.PlaySound(VanillaSoundID.energyShieldHit);
        }
        public override void PostDeath(Entity entity, DeathInfo damageInfo)
        {
            base.PostDeath(entity, damageInfo);
            if (damageInfo.Effects.HasEffect(VanillaDamageEffects.REMOVE_ON_DEATH))
                return;
            var param = entity.GetSpawnParams();
            param.SetProperty(VanillaEntityProps.DAMAGE, entity.GetDamage());
            entity.Spawn(VanillaEffectID.vomitSplash, entity.Position, param);
            entity.PlaySound(VanillaSoundID.splat);
        }
    }
}
